import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce(torch::Tensor x, int64_t dim);
"""

min_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Collapsed contiguous reduction view:
//   X logical: (outer, R, inner) with strides (R*inner, inner, 1)
//   Y logical: (outer, inner)     with strides (inner, 1)
// This is exact for any contiguous input and any reduced dim.
template <int BM, int RS>
__global__ void min_reduce_cute_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int outer, int R, int inner)
{
  const int tid   = threadIdx.x;
  const int lane  = tid % BM;       // output-column tile lane
  const int split = tid / BM;       // reduction split id

  const int tiles = (inner + BM - 1) / BM;
  const int lin   = blockIdx.x;
  const int o     = lin / tiles;
  const int t     = lin - o * tiles;
  const int i     = t * BM + lane;

  const int64_t sOuter = (int64_t)R * inner;
  const int64_t sRed   = (int64_t)inner;
  const int64_t sInner = 1;

  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(outer, R, inner),
      make_stride(sOuter, sRed, sInner));

  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(outer, inner),
      make_stride((int64_t)inner, (int64_t)1));

  __shared__ float sm[RS][BM];

  const bool valid = (i < inner);
  float acc = __int_as_float(0x7f800000); // +inf

  if (valid) {
    // Strided split over R keeps each warp coalesced along `inner`.
    for (int r = split; r < R; r += RS) {
      acc = fminf(acc, mX(o, r, i));
    }
  }

  sm[split][lane] = acc;
  __syncthreads();

  if (split == 0 && valid) {
    float m = sm[0][lane];
    #pragma unroll
    for (int s = 1; s < RS; ++s) {
      m = fminf(m, sm[s][lane]);
    }
    mY(o, i) = m;
  }
}

torch::Tensor min_reduce(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto xc = x.contiguous();
  const int64_t nd = xc.dim();
  TORCH_CHECK(nd >= 1, "x must have at least one dimension");

  if (dim < 0) dim += nd;
  TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");

  int64_t outer = 1;
  for (int64_t d = 0; d < dim; ++d) outer *= xc.size(d);
  const int64_t R = xc.size(dim);
  int64_t inner = 1;
  for (int64_t d = dim + 1; d < nd; ++d) inner *= xc.size(d);
  TORCH_CHECK(R > 0, "cannot reduce over an empty dimension");

  auto out_sizes = xc.sizes().vec();
  out_sizes.erase(out_sizes.begin() + dim);
  auto y = torch::empty(out_sizes, xc.options());
  if (y.numel() == 0) return y;

  constexpr int BM = 128;
  constexpr int RS = 4;
  constexpr int THREADS = BM * RS;

  const int64_t tiles = (inner + BM - 1) / BM;
  const int64_t blocks = outer * tiles;
  TORCH_CHECK(blocks > 0 && blocks < 2147483647LL, "invalid grid size");

  dim3 grid((unsigned)blocks);
  dim3 block(THREADS);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  min_reduce_cute_kernel<BM, RS><<<grid, block, 0, stream>>>(
      xc.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer, (int)R, (int)inner);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "min_reduce_cute_kernel failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=min_cpp_decl,
    cuda_sources=min_cuda_src,
    functions=["min_reduce"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Min reduction over a specified dimension using one custom CUTE/CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = int(dim)
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce(x, self.dim)

